#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> dp(n, 0);
    vector<int> a(n + 1);
    for (int i = 1; i <= n; i++) cin >> a[i];

    for (int i = 1; i <= n; i++) {
        dp[i] = a[i];
        for (int j = i - 1; j >= 1; j--) {
            if (a[i] % a[j] == 0) {
                dp[i] = max(dp[i], dp[j] + a[i]);
            }
        }
    }

    int max_val = 0;
    for (int i = 1; i <= n; i++) {
        max_val = max(max_val, dp[i]);
    }
    cout << max_val << endl;
    return 0;
}
